import React from 'react';

import * as L from 'leaflet';

import { setMarkerSimpleIcon } from '@apps/Routes/@helpers/routeObjects.helper';
import PolylineInfo from '@components/PolylineInfo';

import { getBaseRouteDataAsync, IBaseRouteData } from '../../../Routes/@services/routes.service';
import { RouteObjectType } from '../../../Routes/@types/routes.types';
import { getHikingGpxTrackById } from '../../@services/hikingResults.service';
import { IHikingData, IHikingGpx } from '../../@types/hiking.types';
import { IHikingObstacleOne } from '../../@types/hikingObstacles.types';

interface IHikingObstacleMapProps {
  hikingObstacle: IHikingObstacleOne;
  hikingData: IHikingData;
}

const HikingObstacleMap: React.FC<IHikingObstacleMapProps> = ({ hikingObstacle, hikingData }) => {
  const [track, setTrack] = React.useState<IHikingGpx>();

  const [mapData, setMapData] = React.useState<IBaseRouteData | null>(null);

  const mapRef = React.useRef<L.Map>(null);

  React.useEffect(() => {
    const start = async () => {
      hikingData.route.id && getBaseRouteDataAsync(hikingData.route.id).then(setMapData);
      const trackRes = await getHikingGpxTrackById(hikingObstacle.idHikingTrack);
      setTrack(trackRes);

      if (mapRef.current) {
        const m = new L.Marker(hikingObstacle.obstacle.coordinates);
        setMarkerSimpleIcon(m, 'violet');
        //a.obstacle && setMarkerObstacle(pl, a.obstacle, a.is_in_distance);

        setTimeout(() => mapRef.current && m.addTo(mapRef.current), 1000);
      }
    };

    start();
  }, [hikingObstacle]);

  if (!mapData || !track) return 'Loading';

  const coordinates = track?.track?.find(
    (x) => x.date > hikingObstacle.date_in && x.date < hikingObstacle.date_out,
  )?.point as unknown as [number, number, number];

  return (
    <>
      <PolylineInfo
        height={320}
        points={track?.track.map(({ point: [la, lo, al] }) => [la, lo, al ?? 0]) ?? []}
        mapType={mapData?.typeData}
        poi={[
          {
            type: RouteObjectType.Point,
            coordinates,
            obstacle: hikingObstacle.obstacle,
            id: 0,
            name: hikingObstacle.obstacle.name,
            description: hikingObstacle.obstacle.description,
            is_in_distance: true,
            order: 0,
            dateCreate: '',
            dateUpdate: null,
            updater: null,
          },
        ]}
        ref={mapRef}
      />
    </>
  );
};

export default HikingObstacleMap;
