import React from 'react';

import { useNavigate } from 'react-router-dom';

import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import ObstacleCategoryBadge from '@apps/Obstacles/components/ObstacleCategoryBadge/ObstacleCategoryBadge';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { getDiffDate } from '@helpers/dateHelper';
import { formatAltitude } from '@helpers/formatHelper';
import notificationHelper from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import HikingObstacleMap from './components/HikingObstacleMap';
import HikingObstacleMembers from './components/HikingObstacleMembers';
import HikingObstaclePhotoItem from './components/HikingObstaclePhotoItem';
import { getUrlFromObstacleType } from '../../Obstacles/@mappers/obstacles.url.mapper';
import { obstacleTypeNameResource } from '../../Obstacles/@resources/obstacles.resource';
import { HikingBadgeOneLine } from '../@components/HikingBadge';
import { getBaseHikingFromHikingData } from '../@mappers/hiking.mapper';
import { getHikingDataAsync } from '../@services/hiking.service';
import { deleteHikingObstacle, getHikingOneObstacle } from '../@services/hikingObstacles.service';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { HikingAccessGroup } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { IHikingObstacleOne } from '../@types/hikingObstacles.types';
interface IHikingOneHikingObstaclePageProps {
  id_hiking: number;
  id_hiking_obstacle: number;
  search?: string;
}

const HikingOneHikingObstaclePage: React.FC<IHikingOneHikingObstaclePageProps> = ({
  id_hiking,
  id_hiking_obstacle,
}) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [obstacleData, setObstacleData] = React.useState<IHikingObstacleOne | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [canEdit, setCanEdit] = React.useState(false);

  const navigate = useNavigate();

  React.useEffect(() => {
    const start = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
      await getHikingOneObstacle(id_hiking_obstacle).then(setObstacleData);
      const accessGroup = await getHikingAccessGroupAsync(id_hiking);
      setCanEdit(
        [
          HikingAccessGroup.Full,
          HikingAccessGroup.All,
          HikingAccessGroup.Boss,
          HikingAccessGroup.Routes,
        ].includes(accessGroup),
      );
    };

    start().finally(() => setIsLoading(false));
  }, [id_hiking, id_hiking_obstacle]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) {
    return null;
  }

  if (!obstacleData) {
    return (
      <section>
        <Empty>
          Информация о прохождении этой точки пока не готова. Зайдите позже или посмотрите на{' '}
          <a href={`/hiking/${id_hiking}`}>странице похода</a>
        </Empty>
        <CommentsWidget id_hiking={id_hiking} id_hiking_obstacle={id_hiking_obstacle} />
      </section>
    );
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          { href: `/hiking/${id_hiking}/obstacles`, text: 'Локальные препятствия и POI' },
          {
            href: `/hiking/${id_hiking}/obstacles/${obstacleData.id}`,
            text: obstacleData.obstacle.name,
            active: true,
          },
        ]}
      />
      <PageHeader
        title={
          <span>
            <h3 className="mb-0">
              {obstacleTypeNameResource[obstacleData.obstacle.type]}&nbsp;«
              {obstacleData.obstacle.name}»
            </h3>
          </span>
        }
        subtitle={<HikingBadgeOneLine hiking={getBaseHikingFromHikingData(hikingData)} />}
      >
        <aside className="d-flex align-items-center" style={{ gap: 8 }}>
          {canEdit && (
            <PohButton
              onClick={() =>
                navigate(
                  `/hiking/${id_hiking}/obstacles/${obstacleData.obstacle.id}/${obstacleData.id}/edit`,
                )
              }
              variant={ButtonVariant.Light}
            >
              Редактировать
            </PohButton>
          )}
          {canEdit && (
            <PohButton
              onClick={async () => {
                try {
                  const ok = await confirmModal2(
                    `Удалить ${obstacleData.obstacle.name} из похода ${hikingData.name}?`,
                  );
                  if (!ok) return notificationHelper.warn('Отменено');
                  await deleteHikingObstacle({
                    id: obstacleData.id,
                    id_hiking: hikingData.id,
                  });
                  navigate(`/hiking/${id_hiking}/obstacles`);
                  notificationHelper.success('Удалено');
                } catch (error) {
                  notificationHelper.error((error as Error).message);
                }
              }}
              variant={ButtonVariant.Light}
            >
              Удалить
            </PohButton>
          )}
          <PohButton
            onClick={() =>
              navigate(
                `/obstacles/${getUrlFromObstacleType(obstacleData.obstacle.type)}/${obstacleData.obstacle.id}`,
              )
            }
            variant={ButtonVariant.Light}
            className="ms-2"
          >
            Подробнее
          </PohButton>
        </aside>
      </PageHeader>

      <PohRow>
        <PohCol sm={3}>
          <h5>Общая информация</h5>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Тип:
            </PohCol>
            <PohCol xs={7}>
              <strong>{obstacleTypeNameResource[obstacleData.obstacle.type]}</strong>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Название:
            </PohCol>
            <PohCol xs={7}>
              <strong>{obstacleData.obstacle.name}</strong>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Категория:
            </PohCol>
            <PohCol xs={7}>
              <ObstacleCategoryBadge category={obstacleData.obstacle.category} />
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Высота:
            </PohCol>
            <PohCol xs={7}>{formatAltitude(obstacleData.obstacle.altitude)}</PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Регион:
            </PohCol>
            <PohCol xs={7}>{obstacleData.obstacle.region?.name}</PohCol>
          </PohRow>
        </PohCol>
        <PohCol sm={9}>
          <h5>Основная информация</h5>
          <PohRow className="mb-2">
            <PohCol sm={2} xs={4} className="text-muted text-sm-end">
              Описание:
            </PohCol>
            <PohCol sm={10} xs={8}>
              <em>{obstacleData.description}</em>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol sm={2} xs={4} className="text-muted text-sm-end">
              Вошли:
            </PohCol>
            <PohCol sm={10} xs={8}>
              <strong className="text-success">
                <small>
                  {obstacleData.date_in.toLocaleString(undefined, {
                    dateStyle: 'full',
                    timeStyle: 'short',
                  })}
                </small>
              </strong>
              <br />
              <em>
                <small>{obstacleData.description_in}</small>
              </em>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol sm={2} xs={4} className="text-muted text-sm-end">
              Ушли:
            </PohCol>
            <PohCol sm={10} xs={8}>
              <strong className="text-success">
                <small>
                  {obstacleData.date_out.toLocaleString(undefined, {
                    dateStyle: 'full',
                    timeStyle: 'short',
                  })}
                </small>
              </strong>
              <br />
              <em>
                <small>{obstacleData.description_out}</small>
              </em>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol sm={2} xs={4} className="text-muted text-sm-end">
              Продолж.:
            </PohCol>
            <PohCol sm={10} xs={8}>
              <strong className="text-success">
                <small>
                  {getDiffDate(obstacleData.date_in, obstacleData.date_out).toLocaleTimeString()}
                </small>
              </strong>
            </PohCol>
          </PohRow>
        </PohCol>
      </PohRow>
      <PohRow className="mt-2">
        <PohCol sm={3}>
          <HikingObstacleMembers hikingData={hikingData} hikingObstacle={obstacleData} />
        </PohCol>
        <PohCol sm={9}>
          <h5>Карта</h5>
          <HikingObstacleMap hikingObstacle={obstacleData} hikingData={hikingData} />
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={12}>
          <h5>Фотки</h5>
          <PohRow>
            {obstacleData.photos.map((photo) => {
              return (
                <PohCol key={photo.id} sm={2}>
                  <HikingObstaclePhotoItem photo={photo} />
                </PohCol>
              );
            })}
          </PohRow>
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};

export default HikingOneHikingObstaclePage;
