import React from 'react';

import CheckCircleFill from '@pohodnik/icons/svg/Signs/CheckCircleFill';
import CheckLg from '@pohodnik/icons/svg/Signs/CheckLg';
import XCircle from '@pohodnik/icons/svg/Signs/XCircle';

import PohAva from '@ui-kit/Ava';
import PohList from '@ui-kit/List';

import { getObstacleTypeName } from '../../../Obstacles/@resources/obstacles.resource';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingObstacleOne } from '../../@types/hikingObstacles.types';

interface IHikingObstacleMembersProps {
  hikingObstacle: IHikingObstacleOne;
  hikingData: IHikingData;
}

const HikingObstacleMembers: React.FC<IHikingObstacleMembersProps> = ({
  hikingObstacle,
  hikingData,
}) => {
  const { was, notWas } = hikingData.hikers.reduce<{
    was: IHikingData['hikers'];
    notWas: IHikingData['hikers'];
  }>(
    (acc, hiker) => {
      const f = hikingObstacle.members.find((m) => m.user.id === hiker.idUser);
      if (f) {
        acc.was.push(hiker);
      } else {
        acc.notWas.push(hiker);
      }
      return acc;
    },
    { was: [], notWas: [] },
  );

  return (
    <>
      <h5>Побывавшие участники</h5>
      <PohList
        data={was.map((hiker) => {
          return {
            key: hiker.idUser,
            className: 'py-2',
            children: (
              <div className="d-flex justify-content-between align-items-center">
                <div className="d-flex align-items-center">
                  <PohAva src={hiker.photo[50]} alt={hiker.name} className="me-2" />
                  <small style={{ lineHeight: 1 }}>
                    {hiker.name}
                    <br />
                    {hiker.surname}
                  </small>
                </div>
                <CheckCircleFill className="text-success" />
              </div>
            ),
          };
        })}
      />

      {notWas.length > 0 ? (
        <>
          <h5>Пропустившие участники</h5>
          <PohList
            data={notWas.map((hiker) => {
              return {
                key: hiker.idUser,
                className: 'py-2',
                children: (
                  <div className="d-flex justify-content-between align-items-center">
                    <div className="d-flex align-items-center">
                      <PohAva src={hiker.photo[50]} alt={hiker.name} className="me-2" />
                      <small style={{ lineHeight: 1 }}>
                        {hiker.name}
                        <br />
                        {hiker.surname}
                      </small>
                    </div>
                    <XCircle className="text-danger" />
                  </div>
                ),

                disabled: true,
                style: { opacity: 0.5 },
              };
            })}
          />
        </>
      ) : (
        <small className="text-success">
          <CheckLg /> Все участники похода были на{' '}
          {getObstacleTypeName(hikingObstacle.obstacle.type, 'prepositional').toLowerCase()}
        </small>
      )}
    </>
  );
};

export default HikingObstacleMembers;
